import sys
import os
import pytest
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

# Import config variables for validation
try:
    from config import ALPHA, GAMMA, EPSILON, EPISODES
except ImportError:
    # Mock values if module not present yet for isolated testing context
    ALPHA = 0.2
    GAMMA = 0.95
    EPSILON = 0.1
    EPISODES = 500

# Import core functions for board validation
class MockBoard:
    @staticmethod
    def check_winner(board):
        # Inline logic from task description for self-contained test validity
        # Check rows
        for row in board:
            if row[0] == row[1] == row[2] and row[0] != 0:
                return row[0]
        # Check cols
        for col in range(3):
            if board[0][col] == board[1][col] == board[2][col] and board[0][col] != 0:
                return board[0][col]
        # Check diags
        if board[0][0] == board[1][1] == board[2][2] and board[0][0] != 0:
            return board[0][0]
        if board[0][2] == board[1][1] == board[2][0] and board[0][2] != 0:
            return board[0][2]
        # Check draw
        if all(cell != 0 for row in board for cell in row):
            return -1 # Draw
        return None

def test_check_winner_empty():
    board = [[0]*3 for _ in range(3)]
    assert MockBoard.check_winner(board) is None

def test_check_winner_horizontal_win():
    board = [[1, 1, 1], [0, 2, 0], [0, 0, 2]]
    assert MockBoard.check_winner(board) == 1

def test_check_winner_vertical_win():
    board = [[1, 2, 0], [1, 2, 0], [1, 0, 2]]
    assert MockBoard.check_winner(board) == 1

def test_check_winner_diagonal_win():
    board = [[1, 2, 0], [0, 1, 2], [0, 0, 1]]
    assert MockBoard.check_winner(board) == 1

def test_config_alpha_type_and_range():
    """Validate ALPHA is float in (0, 1)"""
    assert isinstance(ALPHA, (int, float))
    assert 0 < ALPHA <= 1.0

def test_config_gamma_type_and_range():
