\bibitem{hart1968formal} P. E. Hart, N. J. Nilsson, and B. Raphael, \textit{A formal basis for the heuristic determination of minimum cost paths}, IEEE Transactions on Systems Science and Cybernetics, 1968.
\bibitem{pohl1970heuristic} I. Pohl, \textit{Heuristic path searching}, AI Magazine, 1970.
\bibitem{pearl1984heuristics} J. Pearl, \textit{Heuristics: Intelligent Search Strategies for Computer Problem Solving}, Addison-Wesley, 1984.
