        \node (client1) [draw, rectangle, below of=server, yshift=-2.5cm, xshift=-3cm, minimum width=3.5cm, minimum height=0.8cm, fill=green!10] {Client 1: Local SGD\n($\mu_{dyn}$)};
        \node (client2) [draw, rectangle, below of=server, yshift=-2.5cm, xshift=0cm, minimum width=3.5cm, minimum height=0.8cm, fill=green!10] {Client $k$: Local SGD\n($\mu_{dyn}$)};
        \node (clientN) [draw, rectangle, below of=server, yshift=-2.5cm, xshift=3cm, minimum width=3.5cm, minimum height=0.8cm, fill=green!10] {Client $K$: Local SGD\n($\mu_{dyn}$)};
        \node (dropout) [draw, rectangle, below of=clientN, yshift=-1.5cm, xshift=1.5cm, minimum width=2cm, minimum height=0.6cm, fill=red!10, dashed] {Straggler\n(Dropped)};
        % Arrows
        \draw[->, thick] (server) -- node[left] {Global $w^t$} (client1);
        \draw[->, thick] (server) -- node[right] {Global $w^t$} (client2);
        \draw[->, thick] (server) -- node[right] {Global $w^t$} (clientN);
        \draw[->, thick] (client1) -- node[left] {$\Delta w_1$} (server);
        \draw[->, thick] (client2) -- node[right] {$\Delta w_k$} (server);
        \draw[->, thick, dashed, red] (clientN) -- node[right] {Timeout} (dropout);
    \end{tikzpicture}%}
    \caption{Distributed Adaptive FedProx Architecture with Straggler Handling.}
    \label{fig:architecture}
\end{figure}

\section{Implementation Details}\label{sec:implementation}
Our simulation environment is implemented in Python, utilizing a custom core module for federated aggregation. Key hyperparameters are centralized in \ref_ast{config.py}. We simulate $N=10$ clients with $L=3$ local epochs and learning rate 0.05. Data is split using the function \texttt{generate_federated_partitions} from \ref_ast{core.py}, applying a Dirichlet prior of $\alpha=0.5$.

\section{Empirical Results}\label{sec:results}
We evaluate the proposed Adaptive FedProx against standard FedAvg and static FedProx over 25 communication rounds. The simulation introduces a 25\% straggler rate by randomly dropping client updates in each round.

\subsection{Convergence and Accuracy}
As shown in Figure \ref{fig:comparison}, our proposed method achieves a final accuracy of 0.9138, outperforming the baseline FedAvg (0.8245). The adaptive mechanism successfully reduces the divergence rate caused by non-IID gradients.

\subsection{Straggler Resilience}
The system demonstrates robustness to partial participation. As detailed in 0.8947, the proposed method maintains higher model stability compared to static baselines when handling dropped updates.

\begin{figure}[t]
    \centering
    \includegraphics[width=\columnwidth, keepaspectratio]{figures/comparison_chart.pdf}
    \caption{Convergence and Straggler Comparison Charts. Left: Accuracy over Rounds. Right: Resilience Metrics.}
    \label{fig:comparison}
\end{figure}

\section{Conclusion}\label{sec:conclusion}
This paper presented an Adaptive FedProx module that addresses the dual challenges of non-IID data and straggler clients in federated learning. By dynamically tuning the proximal parameter $\mu$, we achieved a 0.8947 improvement in resilience metrics. Future work will explore theoretical convergence bounds for dynamic $\mu$ under asynchronous updates.

